import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.sc8Z_ZE3.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/architecture.md","filePath":"concepts/architecture.md"}'),d={name:"concepts/architecture.md"};function s(n,e,c,i,h,l){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>How the parts of Octryx AI fit together: what runs on the server, what runs on a developer&#39;s machine, and how a request moves through the platform.</p><h2 id="the-parts" tabindex="-1">The parts <a class="header-anchor" href="#the-parts" aria-label="Permalink to &quot;The parts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>Runs where</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Platform</strong> (<code>api</code>)</td><td>your server, in Docker Compose or Kubernetes</td><td>The web app, the REST API, the MCP server for coding clients, workflows and their checks, Knowledge, the review bot, connections, audit</td></tr><tr><td><strong>PostgreSQL</strong></td><td>next to the platform</td><td>All records, and the Knowledge search index</td></tr><tr><td><strong>Object store</strong></td><td>next to the platform (bundled in Compose) or your S3 bucket</td><td>The originals of Knowledge sources, uploads and evidence. See <a href="/docs/install/knowledge-storage">Knowledge storage</a></td></tr><tr><td><strong><code>migrate</code>, <code>secrets-init</code></strong></td><td>once at each start</td><td>Bring the database to the current version; create the keys on the first start. See <a href="/docs/install/upgrade">Upgrade</a></td></tr><tr><td><strong>Launcher <code>octryx-claude</code></strong></td><td>each developer&#39;s machine</td><td>Starts Claude Code under the Workspace&#39;s rules, and as a <strong>device</strong> takes the run phases that change and test code. See <a href="/docs/install/launcher">Launcher and devices</a></td></tr><tr><td><strong>Your tools</strong></td><td>where they are</td><td>Jira, Confluence, GitHub, GitLab, Bitbucket and others, reached through <a href="/docs/connections/">connections</a></td></tr></tbody></table><p>The platform never builds or tests code itself. That happens on a device, in a clone of the repository, with the developer&#39;s own Claude Code. Pushing, opening pull requests and updating tickets happen on the server, so a developer&#39;s machine never holds a Git host or Jira credential. See <a href="/docs/security/network">Network and egress</a>.</p><h2 id="a-run-end-to-end" tabindex="-1">A run, end to end <a class="header-anchor" href="#a-run-end-to-end" aria-label="Permalink to &quot;A run, end to end&quot;">​</a></h2><ol><li>A work item comes in, from Jira, the web app or the chat.</li><li>A <a href="/docs/concepts/workflows">workflow</a> is started on it. The platform decides the phases and their checks.</li><li>For a phase that changes code, the platform hands a job to a paired device. The launcher starts Claude Code there in a clone of the repository, with a phase brief.</li><li>Every tool call passes the launcher&#39;s check first; every model call passes the platform&#39;s gateway with its policy, budget and secret scan.</li><li>After the phase the platform runs its own checks: the declared tests without the agent, the proof that a new test fails on the old code, an independent review. See <a href="/docs/concepts/evidence">Evidence and checks</a>.</li><li>The platform pushes the branch, opens the pull request and reports back to the ticket. The <a href="/docs/review-bot/">review bot</a> reviews the pull request.</li><li>Everything lands in the run&#39;s record: phases, evidence, tokens and cost. See <a href="/docs/concepts/runs">Runs and their record</a>.</li></ol><h2 id="inside-the-platform" tabindex="-1">Inside the platform <a class="header-anchor" href="#inside-the-platform" aria-label="Permalink to &quot;Inside the platform&quot;">​</a></h2><p>The backend is one Python application (<code>backend/app</code> in the repository):</p><table tabindex="0"><thead><tr><th>Area</th><th>Owns</th></tr></thead><tbody><tr><td><code>api/routes</code>, <code>web/routers</code></td><td>HTTP: <code>/api/v1</code> is the API; the web app also uses its own <code>/chat/api</code> routes</td></tr><tr><td><code>services</code></td><td>Business logic, policies and orchestration</td></tr><tr><td><code>services/session</code></td><td>A chat or agent turn: preparation, dispatch, completion, and the <strong>execution gate</strong></td></tr><tr><td><code>agent/engine</code></td><td>Dispatch to the model provider, retry, fallback and budget</td></tr><tr><td><code>agent/core</code></td><td>A turn&#39;s context, prompts and the standard loop</td></tr><tr><td><code>agent/providers</code></td><td>The model providers&#39; clients, such as Bedrock, OpenRouter and Ollama</td></tr><tr><td><code>tools</code></td><td>Tool definitions, registry, visibility and dispatch, with each tool&#39;s risk and approval metadata; deny by default</td></tr></tbody></table><p>A turn goes: route → session dispatch → <code>agent/engine</code> → the turn&#39;s <strong>execution profile</strong> → the <strong>execution gate</strong>, which never starts the loop for a profile that is not allowed → the standard loop → tool dispatch, where the registry, the visibility rules and the tool access policy decide what may run.</p><p>The web app is a React application in <code>frontend/chat</code>. Its look and its rules are in the <a href="/docs/contribute/design-guide">design guide</a>.</p>',12)])])}const g=t(d,[["render",s]]);export{u as __pageData,g as default};
